<template>
  <view class="page auth-page">
    <view class="content">
      <view class="auth-hero">
        <view class="tag tag-orange">账号中心</view>
        <view class="auth-title">登录 / 注册学徒行</view>
        <view class="sub">登录后可同步平台消息、客服历史记录、收藏路线与积分权益。</view>
      </view>

      <view class="tabs">
        <view class="tab" :class="{ on: tab === 'login' }" @click="tab = 'login'">登录</view>
        <view class="tab" :class="{ on: tab === 'register' }" @click="tab = 'register'">注册</view>
      </view>

      <view class="card auth-card">
        <view class="form-item">
          <view class="label">手机号</view>
          <input v-model.trim="form.phone" class="input" type="number" maxlength="11" placeholder="请输入 11 位手机号" />
        </view>
        <view class="form-item" v-if="tab === 'register'">
          <view class="label">昵称</view>
          <input v-model.trim="form.nickname" class="input" placeholder="给自己取一个昵称" />
        </view>
        <view class="form-item" v-if="tab === 'register'">
          <view class="label-row">
            <view class="label">邀请码（选填）</view>
            <text class="scan-link" @click="scanInvite">扫一扫</text>
          </view>
          <input v-model.trim="form.inviteCode" class="input" maxlength="64" placeholder="扫描好友二维码或填写邀请码" />
          <view v-if="form.inviteCode" class="invite-bound">✓ 已识别邀请码 {{ form.inviteCode }}</view>
        </view>
        <view class="form-item">
          <view class="label">密码</view>
          <input v-model.trim="form.password" class="input" password maxlength="50" placeholder="请输入密码（至少 6 位）" />
        </view>
        <view v-if="tab === 'register'" class="auth-tip">注册提交后需要管理员审核，通过后才可以登录。</view>
        <view v-if="tab === 'register'" class="agreement-line">
          注册即表示同意
          <text @click="openArticle('user-agreement')">《用户协议》</text>
          和
          <text @click="openArticle('privacy-policy')">《隐私政策》</text>
        </view>
        <view class="btn btn-primary" @click="submit">{{ tab === 'login' ? '立即登录' : '提交注册申请' }}</view>
      </view>

      <view class="api-diagnostic">
        <view class="api-status"><text :class="['api-dot',{ok:diagnosticOk}]"></text><b>API 连接诊断</b></view>
        <text class="api-url">{{ apiUrl }}</text>
        <view class="api-test" @click="checkApi">{{ checking ? '检测中...' : '检测公网连接' }}</view>
      </view>
    </view>
  </view>
</template>

<script setup>
import { reactive, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { getApiBaseUrl, getInviteDeviceId, loginUser, registerUser, testApiConnection } from '../../utils/api.js'

const tab = ref('login')
const form = reactive({ phone: '', nickname: '', password: '', inviteCode: '' })
const apiUrl = ref(getApiBaseUrl())
const checking = ref(false)
const diagnosticOk = ref(false)

const parseInviteCode = value => {
  const text = decodeURIComponent(String(value || '').trim())
  if (!text) return ''
  if (text.startsWith('XTXINVITE:')) return text.slice('XTXINVITE:'.length).trim()
  const match = text.match(/[?&](?:invite_code|inviteCode)=([^&#]+)/i)
  return match ? decodeURIComponent(match[1]) : text
}

const applyInviteCode = value => {
  const code = parseInviteCode(value)
  if (!code) return false
  form.inviteCode = code
  tab.value = 'register'
  uni.setStorageSync('pendingInviteCode', code)
  return true
}

const scanInvite = () => {
  uni.scanCode({
    scanType: ['qrCode'],
    success: result => {
      if (applyInviteCode(result.result)) uni.showToast({ title: '邀请码识别成功', icon: 'success' })
      else uni.showToast({ title: '未识别到有效邀请码', icon: 'none' })
    },
    fail: error => {
      if (!String(error?.errMsg || '').includes('cancel')) {
        uni.showToast({ title: '扫码失败，请手动填写邀请码', icon: 'none' })
      }
    },
  })
}

onLoad(options => {
  const code = options?.invite_code || options?.inviteCode || options?.scene || uni.getStorageSync('pendingInviteCode')
  if (code) applyInviteCode(code)
})

const checkApi = async () => {
  if (checking.value) return
  checking.value = true
  const result = await testApiConnection()
  checking.value = false
  diagnosticOk.value = result.ok
  apiUrl.value = result.apiBaseUrl
  uni.showModal({
    title: result.ok ? '连接正常' : '连接失败',
    content: `请求地址：${result.healthUrl}\n状态：${result.statusCode || '未到达服务器'}\n耗时：${result.elapsed}ms\n结果：${result.message}`,
    showCancel: false,
  })
}

const backOrHome = () => {
  const pages = getCurrentPages()
  if (pages.length > 1) uni.navigateBack()
  else uni.reLaunch({ url: '/pages/mine/index' })
}

const openArticle = slug => {
  uni.navigateTo({ url: `/pages/article/detail?slug=${slug}` })
}

const submit = async () => {
  if (!form.phone || !form.password || (tab.value === 'register' && !form.nickname)) {
    uni.showToast({ title: '请填写完整信息', icon: 'none' })
    return
  }
  if (!/^1\d{10}$/.test(form.phone)) {
    uni.showToast({ title: '请输入正确的 11 位手机号', icon: 'none' })
    return
  }
  if (form.password.length < 6) {
    uni.showToast({ title: '密码至少需要 6 位', icon: 'none' })
    return
  }
  if (tab.value === 'register' && form.nickname.length > 60) {
    uni.showToast({ title: '昵称不能超过 60 个字符', icon: 'none' })
    return
  }
  try {
    if (tab.value === 'login') {
      await loginUser({ account: form.phone, password: form.password })
      uni.showToast({ title: '登录成功', icon: 'success' })
      setTimeout(backOrHome, 500)
      return
    }

    const result = await registerUser({
      phone: form.phone,
      nickname: form.nickname,
      password: form.password,
      invite_code: form.inviteCode,
      device_id: getInviteDeviceId(),
    })
    uni.showToast({ title: result.message || '注册申请已提交', icon: 'none', duration: 2200 })
    if (result.invitation_bound) uni.removeStorageSync('pendingInviteCode')
    tab.value = 'login'
    form.password = ''
  } catch (error) {
    uni.showToast({ title: error.message || '操作失败', icon: 'none' })
  }
}
</script>

<style scoped>
.auth-page{background:linear-gradient(180deg,#fff8ef,#eef8f4)}
.auth-hero{padding:36rpx 32rpx;background:#173f39;color:#fff;border-radius:30rpx;margin-bottom:24rpx}
.auth-title{font-size:40rpx;font-weight:900;margin:18rpx 0 12rpx}
.auth-card{padding:10rpx 26rpx 30rpx}
.label-row{display:flex;align-items:center;justify-content:space-between}.scan-link{color:#0d8f80;font-size:24rpx;font-weight:700}
.invite-bound{margin-top:12rpx;color:#0d8f80;font-size:22rpx}
.auth-tip{margin:4rpx 0 24rpx;color:#6f7e7a;font-size:24rpx;line-height:1.7}
.agreement-line{margin:-8rpx 0 24rpx;color:#80908c;font-size:22rpx;line-height:1.7}.agreement-line text{color:#0d8f80;font-weight:700}
.api-diagnostic{margin-top:22rpx;padding:22rpx;border:1rpx solid #dce7e3;border-radius:22rpx;background:rgba(255,255,255,.76)}
.api-status{display:flex;align-items:center;gap:10rpx}.api-status b{font-size:24rpx}.api-dot{width:14rpx;height:14rpx;border-radius:50%;background:#aab5b2}.api-dot.ok{background:#12a594;box-shadow:0 0 0 7rpx rgba(18,165,148,.12)}
.api-url{display:block;margin:14rpx 0;color:#657873;font-size:20rpx;line-height:1.5;word-break:break-all}
.api-test{padding:15rpx;border-radius:15rpx;background:#173f39;color:#fff;text-align:center;font-size:22rpx}
</style>
